steps.name:
$ErrorActionPreference = 'Stop'
                            $ok = $false
                            for ($i = 0; $i -lt 10; $i++) {
                                try {
                                    Invoke-WebRequest -Uri "$env:PARABANK_URL/index.htm" -UseBasicParsing | Out-Null
                                    Start-Sleep -Seconds 5
                                    $ok = $true
                                    break
                                } catch {
                                    Start-Sleep -Seconds 3
                                }
                            }
                            if (-not $ok) {
                                throw "ParaBank did not become ready in time."
                            }
